#!/bin/bash
# VISNEX - Create 100 premium fashion products in WooCommerce
WC_KEY="${WC_CONSUMER_KEY:?Falta WC_CONSUMER_KEY}"
WC_SECRET="${WC_CONSUMER_SECRET:?Falta WC_CONSUMER_SECRET}"
WC_URL="http://localhost:8850/wp-json/wc/v3"
AUTH="-u $WC_KEY:$WC_SECRET"

create_product() {
  local name="$1" desc="$2" short="$3" price="$4" cat_id="$5" img="$6" alt="$7"
  curl -s $AUTH -X POST "$WC_URL/products" -H "Content-Type: application/json" -d "{
    \"name\": \"$name\",
    \"type\": \"simple\",
    \"regular_price\": \"$price\",
    \"description\": \"$desc\",
    \"short_description\": \"$short\",
    \"categories\": [{\"id\": $cat_id}],
    \"images\": [{\"src\": \"$img\", \"alt\": \"$alt\"}],
    \"status\": \"publish\",
    \"manage_stock\": false
  }" > /dev/null 2>&1
  echo "  Created: $name ($price COP)"
}

echo "===== VISNEX - Creating 100 Premium Products ====="
echo ""

